mapper.select:
SELECT COUNT(productid)
FROM P_CART 
WHERE USRNO = #{usrno} 
and productid = #{productid}

SELECT p.qty - NVL(c.qty, 0) - #{qty} AS qty
FROM PRODUCTS p
LEFT JOIN P_CART c
	ON p.productid = c.productid
	AND c.usrno = #{usrno}
WHERE p.productid = #{productid}

mapper.update:
UPDATE P_CART
SET QTY = QTY + #{qty}
WHERE USRNO = #{usrno}
AND PRODUCTID = #{productid}

mapper.delete:
DELETE FROM P_CART
WHERE USRNO = #{usrno}
AND PRODUCTID = #{productid}
